// *** JAVA 7 STYLE: anonymous classes — verbose, 5+ lines per Comparator ***
package com.bank.sorting.service;

import com.bank.sorting.dto.SortedTradesResponse;
import com.bank.sorting.dto.SortedTradesResponse.TradeDetail;
import com.bank.sorting.model.Trade;
import com.bank.sorting.repository.TradeRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.util.*;

@Service
@RequiredArgsConstructor
@Slf4j
public class AnonymousClassSortingService {

    private final TradeRepository tradeRepo;

    @Transactional(readOnly = true)
    public SortedTradesResponse sortByAmountDescAnonymous() {
        List<Trade> trades = new ArrayList<>(tradeRepo.findByStatus("SETTLED"));

        // ANONYMOUS CLASS: 5 lines for a simple sort!
        trades.sort(new Comparator<Trade>() {
            @Override
            public int compare(Trade a, Trade b) {
                return b.getAmount().compareTo(a.getAmount()); // descending
            }
        });

        log.info("[ANONYMOUS] Sorted {} trades by amount desc — 5 lines of boilerplate!", trades.size());

        // ANONYMOUS CLASS for filtering: another 5+ lines!
        List<Trade> largeTrades = new ArrayList<>();
        BigDecimal threshold = new BigDecimal("100000");
        for (Trade trade : trades) {
            if (trade.getAmount().compareTo(threshold) > 0) {
                largeTrades.add(trade);
            }
        }

        List<TradeDetail> details = new ArrayList<>();
        for (Trade t : largeTrades) {
            details.add(new TradeDetail(t.getTradeId(), t.getSymbol(), t.getAmount(),
                t.getTradeDate().toString()));
        }

        return new SortedTradesResponse("amount DESC", "ANONYMOUS_CLASS",
            details.size(), details);
    }
}
