// *** JAVA 8 STYLE: lambdas + method references — concise, readable ***
package com.bank.sorting.service;

import com.bank.sorting.dto.SortedTradesResponse;
import com.bank.sorting.dto.SortedTradesResponse.TradeDetail;
import com.bank.sorting.model.Trade;
import com.bank.sorting.repository.TradeRepository;
import lombok.RequiredArgsConstructor;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.BigDecimal;
import java.util.Comparator;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;

@Service
@RequiredArgsConstructor
@Slf4j
public class LambdaSortingService {

    private final TradeRepository tradeRepo;

    // Reusable Comparators as static constants (lambdas + method references)
    private static final Comparator<Trade> BY_AMOUNT_DESC =
        Comparator.comparing(Trade::getAmount).reversed();

    private static final Comparator<Trade> BY_SYMBOL_THEN_AMOUNT =
        Comparator.comparing(Trade::getSymbol)
            .thenComparing(Trade::getAmount, Comparator.reverseOrder());

    private static final Comparator<Trade> BY_DATE_DESC =
        Comparator.comparing(Trade::getTradeDate).reversed();

    @Transactional(readOnly = true)
    public SortedTradesResponse sortByAmountDescLambda() {
        BigDecimal threshold = new BigDecimal("100000"); // effectively final — captured by lambda

        // LAMBDA: entire sort + filter + map in ONE readable pipeline
        List<TradeDetail> details = tradeRepo.findByStatus("SETTLED").stream()
            .sorted(BY_AMOUNT_DESC)                                              // lambda Comparator
            .filter(t -> t.getAmount().compareTo(threshold) > 0)                 // lambda Predicate
            .map(t -> new TradeDetail(t.getTradeId(), t.getSymbol(),            // lambda Function
                t.getAmount(), t.getTradeDate().toString()))
            .toList();

        log.info("[LAMBDA] Sorted + filtered + mapped in ONE pipeline — 4 lines!");
        return new SortedTradesResponse("amount DESC", "LAMBDA", details.size(), details);
    }

    @Transactional(readOnly = true)
    public SortedTradesResponse sortBySymbolThenAmount() {
        // COMPOSABLE: Comparator.comparing().thenComparing() — no anonymous class
        List<TradeDetail> details = tradeRepo.findByStatus("SETTLED").stream()
            .sorted(BY_SYMBOL_THEN_AMOUNT)
            .map(t -> new TradeDetail(t.getTradeId(), t.getSymbol(),
                t.getAmount(), t.getTradeDate().toString()))
            .toList();

        return new SortedTradesResponse("symbol ASC, amount DESC", "LAMBDA",
            details.size(), details);
    }

    // EFFECTIVELY FINAL CAPTURE demonstration
    @Transactional(readOnly = true)
    public SortedTradesResponse demonstrateCapture() {
        BigDecimal minAmount = new BigDecimal("50000"); // effectively final — OK to capture
        // minAmount = BigDecimal.ZERO; // COMPILE ERROR! Not effectively final anymore!

        // Mutable capture workaround: AtomicInteger (reference is final, value is mutable)
        AtomicInteger counter = new AtomicInteger(0);

        List<TradeDetail> details = tradeRepo.findByStatus("SETTLED").stream()
            .filter(t -> t.getAmount().compareTo(minAmount) > 0)  // captures minAmount
            .peek(t -> counter.incrementAndGet())                   // captures counter (mutable via Atomic)
            .sorted(BY_DATE_DESC)
            .map(t -> new TradeDetail(t.getTradeId(), t.getSymbol(),
                t.getAmount(), t.getTradeDate().toString()))
            .toList();

        log.info("[CAPTURE] Processed {} trades above Rs.{} (counter={})",
            details.size(), minAmount, counter.get());

        return new SortedTradesResponse("date DESC (amount > " + minAmount + ")", "LAMBDA_CAPTURE",
            details.size(), details);
    }
}
