        when(small.getAmount()).thenReturn(new BigDecimal("50000"));
        when(small.getTradeId()).thenReturn("TRD-005");
        when(small.getSymbol()).thenReturn("WIPRO");
        when(small.getTradeDate()).thenReturn(LocalDate.of(2024, 1, 13));

        Trade large = mock(Trade.class);
        when(large.getAmount()).thenReturn(new BigDecimal("245050"));
