        when(trade.getSymbol()).thenReturn("RELIANCE");
        when(trade.getTradeDate()).thenReturn(LocalDate.of(2024, 1, 15));
        when(tradeRepo.findByStatus("SETTLED")).thenReturn(List.of(trade));

        SortedTradesResponse response = service.demonstrateCapture();

        assertThat(response.count()).isEqualTo(1);
        assertThat(response.sortedBy()).contains("50000"); // captured threshold
