  ═══ LAMBDA (Java 8) — 4 lines ═══

  trades.stream()
      .sorted(Comparator.comparing(Trade::getAmount).reversed())  // method ref
      .filter(t -> t.getAmount().compareTo(threshold) > 0)        // lambda
